--

DROP TABLE IF EXISTS `batteries`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `batteries` (
  `id` int NOT NULL AUTO_INCREMENT,
  `battery_code` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL,
  `battery_model` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `battery_serial` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `brand` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `capacity` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `voltage` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT '12V',
  `battery_type` enum('lead_acid','lithium_ion','gel','agm','tubular','other') COLLATE utf8mb4_unicode_ci DEFAULT 'lead_acid',
  `category` enum('inverter','solar','ups','automotive','other') COLLATE utf8mb4_unicode_ci DEFAULT 'inverter',
  `specifications` text COLLATE utf8mb4_unicode_ci,
  `purchase_date` date DEFAULT NULL,
  `warranty_period` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `amc_period` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT '0',
  `price` decimal(10,2) DEFAULT '0.00',
