DROP TABLE IF EXISTS `service_orders_backup`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `service_orders_backup` (
  `id` int NOT NULL DEFAULT '0',
  `service_code` varchar(20) COLLATE utf8mb4_general_ci NOT NULL,
  `customer_id` int NOT NULL,
  `customer_phone` varchar(20) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `battery_id` int NOT NULL,
  `service_staff_id` int DEFAULT NULL,
  `issue_description` text COLLATE utf8mb4_general_ci NOT NULL,
  `warranty_status` enum('in_warranty','extended_warranty','out_of_warranty') COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'out_of_warranty',
  `amc_status` enum('active','expired','no_amc') COLLATE utf8mb4_general_ci DEFAULT 'no_amc',
  `estimated_cost` decimal(10,2) NOT NULL,
  `final_cost` decimal(10,2) DEFAULT NULL,
  `payment_status` enum('pending','partial','paid','refunded') COLLATE utf8mb4_general_ci DEFAULT 'pending',
  `estimated_completion_date` date NOT NULL,
  `status` enum('pending','scheduled','charging','testing','repair','completed','ready','delivered','cancelled','in_progress') COLLATE utf8mb4_general_ci DEFAULT 'pending',
  `priority` enum('urgent','high','medium','low') COLLATE utf8mb4_general_ci DEFAULT 'medium',
  `notes` text COLLATE utf8mb4_general_ci,
  `deposit_amount` decimal(10,2) DEFAULT '0.00',
  `replacement_battery_serial` varchar(100) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `battery_claim` enum('shop_claim','company_claim','none') COLLATE utf8mb4_general_ci DEFAULT 'shop_claim',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
