/*!50013 DEFINER=`root`@`localhost` SQL SECURITY INVOKER */
/*!50001 VIEW `spare_battery_stats` AS select count(0) AS `total_spares`,sum(`spare_batteries`.`quantity`) AS `total_units`,sum((case when (`spare_batteries`.`current_condition` = 'New') then 1 else 0 end)) AS `new_count`,sum((case when (`spare_batteries`.`current_condition` = 'Good') then 1 else 0 end)) AS `good_count`,sum((case when (`spare_batteries`.`current_condition` = 'Fair') then 1 else 0 end)) AS `fair_count`,sum((case when (`spare_batteries`.`current_condition` = 'Poor') then 1 else 0 end)) AS `poor_count`,sum((case when (`spare_batteries`.`current_condition` = 'Defective') then 1 else 0 end)) AS `defective_count`,sum((case when (`spare_batteries`.`quantity` <= `spare_batteries`.`min_quantity`) then 1 else 0 end)) AS `low_stock_count`,sum((case when ((`spare_batteries`.`purchase_date` is not null) and (`spare_batteries`.`warranty_months` > 0) and ((`spare_batteries`.`purchase_date` + interval `spare_batteries`.`warranty_months` month) >= curdate())) then 1 else 0 end)) AS `active_warranty_count` from `spare_batteries` */;
